    40  // This is an interface for an abstract stream class which is used for writing
    41  // the serialised results out.
    42  // -----------------------------------------------------------------------------
    43  class OTSStream {
    44   public:
    45    OTSStream() : chksum_(0) {}
    46
    47    virtual ~OTSStream() {}
    48
    49    // This should be implemented to perform the actual write.
    50    virtual bool WriteRaw(const void *data, size_t length) = 0;
    51
    52    bool Write(const void *data, size_t length) {
    53      if (!length) return false;
    54
    55      const size_t orig_length = length;
    56      size_t offset = 0;
    57
    58      size_t chksum_offset = Tell() & 3;
    59      if (chksum_offset) {
    60        const size_t l = std::min(length, static_cast<size_t>(4) - chksum_offset);
    61        uint32_t tmp = 0;
    62        std::memcpy(reinterpret_cast<uint8_t *>(&tmp) + chksum_offset, data, l);
    63        chksum_ += ntohl(tmp);
    64        length -= l;
    65        offset += l;
    66      }
    67
    68      while (length >= 4) {
    69        uint32_t tmp;
    70        std::memcpy(&tmp, reinterpret_cast<const uint8_t *>(data) + offset,
    71          sizeof(uint32_t));
    72        chksum_ += ntohl(tmp);
    73        length -= 4;
    74        offset += 4;
    75      }
    76
    77      if (length) {
    78        if (length > 4) return false;  // not reached
    79        uint32_t tmp = 0;
    80        std::memcpy(&tmp,
    81                    reinterpret_cast<const uint8_t*>(data) + offset, length);
    82        chksum_ += ntohl(tmp);
    83      }
    84
    85      return WriteRaw(data, orig_length);
    86    }
    87
    88    virtual bool Seek(off_t position) = 0;
    89    virtual off_t Tell() const = 0;
    90
    91    virtual bool Pad(size_t bytes) {
    92      static const uint32_t kZero = 0;
    93      while (bytes >= 4) {
    94        if (!Write(&kZero, 4)) return false;
    95        bytes -= 4;
    96      }
    97      while (bytes) {
    98        static const uint8_t kZerob = 0;
    99        if (!Write(&kZerob, 1)) return false;
   100        bytes--;
   101      }
   102      return true;
   103    }
   104
   105    bool WriteU8(uint8_t v) {
   106      return Write(&v, sizeof(v));
   107    }
   108
   109    bool WriteU16(uint16_t v) {
   110      v = htons(v);
   111      return Write(&v, sizeof(v));
   112    }
   113
   114    bool WriteS16(int16_t v) {
   115      v = htons(v);
   116      return Write(&v, sizeof(v));
   117    }
   118
   119    bool WriteU24(uint32_t v) {
   120      v = htonl(v);
   121      return Write(reinterpret_cast<uint8_t*>(&v)+1, 3);
   122    }
   123
   124    bool WriteU32(uint32_t v) {
   125      v = htonl(v);
   126      return Write(&v, sizeof(v));
   127    }
   128
