    17  // Entry point for LibFuzzer.
    18  extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    19    ots::OTSContext context;
    20    ots::ExpandingMemoryStream stream(size /*initial*/, size * 8 /*limit*/);
    21    bool ok = context.Process(&stream, data, size);
    22
    23    if (ok) {
    24      ots::Buffer file(data, size);
    25      uint32_t tag;
    26      if (file.ReadU32(&tag) && tag == OTS_TAG('t','t','c','f')) {
    27        uint32_t num_fonts;
    28        if (file.Skip(sizeof(uint32_t)) && file.ReadU32(&num_fonts)) {
    29          for (uint32_t i = 0; i < num_fonts; i++) {
    30            stream.Seek(0);
    31            context.Process(&stream, data, size, i);
    32          }
    33        }
    34      }
    35    }
    36
    37    return 0;
    38  }
