   456  bool ProcessWOFF2(ots::FontFile *header,
   457                    ots::OTSStream *output,
   458                    const uint8_t *data,
   459                    size_t length,
   460                    uint32_t index) {
   461    size_t decompressed_size = woff2::ComputeWOFF2FinalSize(data, length);
   462
   463    if (decompressed_size == 0) {
   464      return OTS_FAILURE_MSG_HDR("Size of decompressed WOFF 2.0 is set to 0");
   465    }
   466    // decompressed font must be <= 30MB
   467    if (decompressed_size > 30 * 1024 * 1024) {
   468      return OTS_FAILURE_MSG_HDR("Size of decompressed WOFF 2.0 font exceeds 30MB");
   469    }
   470
