   506  bool GetTableData(const uint8_t *data,
   507                    const ots::TableEntry& table,
   508                    Arena *arena,
   509                    size_t *table_length,
   510                    const uint8_t **table_data) {
   511    if (table.uncompressed_length != table.length) {
   512      // Compressed table. Need to uncompress into memory first.
   513      *table_length = table.uncompressed_length;
   514      *table_data = (*arena).Allocate(*table_length);
   515      uLongf dest_len = *table_length;
   516      int r = uncompress((Bytef*) *table_data, &dest_len,
   517                         data + table.offset, table.length);
   518      if (r != Z_OK || dest_len != *table_length) {
   519        return false;
   520      }
   521    } else {
   522      // Uncompressed table. We can process directly from memory.
   523      *table_data = data + table.offset;
   524      *table_length = table.length;
   525    }
   526
   527    return true;
   528  }
